'use client';
import { motion } from 'framer-motion';


export default function PremiumTextReveal({ text }: { text: string }) {
  const words = text.split(' ');
  const container = {
    hidden: { opacity: 0 },
    visible: { opacity: 1, transition: { staggerChildren: 0.1, delayChildren: 0.2 } },
  };
  const child = {
    visible: { opacity: 1, y: 0, transition: { type: 'spring', damping: 12, stiffness: 100 } },
    hidden: { opacity: 0, y: 50 },
  };


  return (
    <motion.div variants={container} initial="hidden" animate="visible" className="flex flex-wrap gap-2 overflow-hidden">
      {words.map((word, index) => (
        <motion.span variants={child} key={index} className="inline-block">{word}</motion.span>
      ))}
    </motion.div>
  );
}


