      <Canvas camera={{ position: [0, 0, 6] }}>
        <ambientLight intensity={0.8} />
        <Suspense fallback={<Loader />}>
          <Float speed={2} rotationIntensity={1} floatIntensity={2}>
            {/* כאן תכניס את מודל ה-GLB שלך בעתיד */}
