'use client';
import { motion, useMotionValue, useSpring, useTransform } from 'framer-motion';
import { MouseEvent, ReactNode, useRef } from 'react';


export default function MagneticButton({ children }: { children: ReactNode }) {
  const ref = useRef<HTMLDivElement>(null);
  const x = useMotionValue(0);
  const y = useMotionValue(0);
  
  const mouseXSpring = useSpring(x, { stiffness: 150, damping: 15, mass: 0.1 });
  const mouseYSpring = useSpring(y, { stiffness: 150, damping: 15, mass: 0.1 });


  const handleMouseMove = (e: MouseEvent<HTMLDivElement>) => {
    if (!ref.current) return;
    const { height, width, left, top } = ref.current.getBoundingClientRect();
    const middleX = e.clientX - (left + width / 2);
    const middleY = e.clientY - (top + height / 2);
    x.set(middleX * 0.3); // עוצמת המגנט
    y.set(middleY * 0.3);
  };


  const handleMouseLeave = () => { x.set(0); y.set(0); };


  return (
    <motion.div ref={ref} onMouseMove={handleMouseMove} onMouseLeave={handleMouseLeave} style={{ x: mouseXSpring, y: mouseYSpring }} className="inline-block cursor-pointer">
      {children}
    </motion.div>
  );
}


'use client';
import { motion, useScroll, useTransform } from 'framer-motion';
import { useRef } from 'react';


export default function ParallaxImage({ src, alt }: { src: string, alt: string }) {
  const ref = useRef(null);
  const { scrollYProgress } = useScroll({ target: ref, offset: ["start end", "end start"] });
  const y = useTransform(scrollYProgress, [0, 1], ["-15%", "15%"]); // טווח התזוזה


  return (
    <div ref={ref} className="overflow-hidden w-full h-[400px] relative rounded-2xl">
      <motion.img style={{ y }} src={src} alt={alt} className="absolute inset-0 w-full h-[130%] object-cover" />
    </div>
  );
}


