17. אפקט הקלדת מסוף (Terminal Typing) הטקסט מוקלד אות אחרי אות, עם סמן מהבהב. קלאסי לסטארט-אפים.
TypeScript
'use client';
import { motion } from 'framer-motion';
import { useState, useEffect } from 'react';


export default function TypingEffect({ text }: { text: string }) {
  const [displayedText, setDisplayedText] = useState("");
  
  useEffect(() => {
    let i = 0;
    const interval = setInterval(() => {
      setDisplayedText(text.slice(0, i + 1));
      i++;
      if (i === text.length) clearInterval(interval);
    }, 100);
    return () => clearInterval(interval);
  }, [text]);


  return (
    <div className="text-green-400 font-mono text-2xl">
      {displayedText}
      <motion.span animate={{ opacity: [0, 1, 0] }} transition={{ repeat: Infinity, duration: 0.8 }}>_</motion.span>
    </div>
  );
}


