'use client';
import { motion, useMotionValue, useTransform } from 'framer-motion';  
import { MouseEvent, ReactNode } from 'react';

export default function TiltCard({ children }: { children: ReactNode }) {  
  const x = useMotionValue(200);  
  const y = useMotionValue(200);

  const rotateX = useTransform(y, [0, 400], [10, -10]);  
  const rotateY = useTransform(x, [0, 400], [-10, 10]);

  function handleMouse(event: MouseEvent<HTMLDivElement>) {  
    const rect = event.currentTarget.getBoundingClientRect();  
    x.set(event.clientX - rect.left);  
    y.set(event.clientY - rect.top);  
  }

  function handleMouseLeave() {  
    x.set(200); y.set(200); // איפוס למרכז  
  }

  return (  
    <motion.div  
      onMouseMove={handleMouse} onMouseLeave={handleMouseLeave}  
      style={{ rotateX, rotateY, perspective: 1000 }}  
      className="w-full max-w-sm rounded-xl border border-gray-200 shadow-xl bg-white p-8 transition-shadow hover:shadow-2xl"  
    >  
      {children}  
    </motion.div>  
  );  
}

