'use client';
import { motion, useSpring } from 'framer-motion';  
import { useEffect, useState } from 'react';

export default function CustomCursor() {  
  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });  
  const springConfig = { damping: 25, stiffness: 300, mass: 0.5 };  
  const cursorX = useSpring(mousePosition.x, springConfig);  
  const cursorY = useSpring(mousePosition.y, springConfig);

  useEffect(() => {  
    const updateMousePosition = (e: globalThis.MouseEvent) => setMousePosition({ x: e.clientX, y: e.clientY });  
    window.addEventListener('mousemove', updateMousePosition);  
    return () => window.removeEventListener('mousemove', updateMousePosition);  
  }, []);

  return (  
    <motion.div  
      className="fixed top-0 left-0 w-8 h-8 rounded-full border-2 border-black pointer-events-none z-50 mix-blend-difference"  
      style={{ x: cursorX, y: cursorY, translateX: '-50%', translateY: '-50%' }}  
    />  
  );  
}

